CREATE FUNCTION public.enforce_task_evidence() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='done' AND OLD.status IS DISTINCT FROM 'done' AND EXISTS(SELECT 1 FROM checklist_templates t WHERE t.id=NEW.template_id AND t.gate_code='gate_d' AND t.evidence_required) AND coalesce(trim(NEW.evidence_url),'')='' THEN RAISE EXCEPTION 'Gate D task needs an evidence link or uploaded file before it can be marked Done'; END IF; RETURN NEW; END $$; REVOKE ALL ON FUNCTION public.enforce_task_evidence() FROM PUBLIC,anon,authenticated; CREATE TRIGGER a_gate_d_evidence BEFORE UPDATE ON public.client_tasks FOR EACH ROW EXECUTE FUNCTION public.enforce_task_evidence();